styleContent:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap');

:root {
    --bg: #f5f5f5;
    --surface: #ffffff;
    --border: #cccccc;
    --border-light: #e0e0e0;
    --text: #111111;
    --text-secondary: #555555;
    --accent: #222222;
    --accent-light: #f0f0f0;
    --accent-mid: #444444;
    --red: #333333;
    --red-light: #f5f5f5;
    --green: #333333;
    --green-light: #f5f5f5;
    --yellow-light: #fafafa;
    --yellow-border: #cccccc;
    --section-1: #222222;
    --section-2: #333333;
    --section-3: #444444;
    --section-4: #555555;
    --radius: 6px;
    --shadow: 0 1px 4px rgba(0, 0, 0, .08);
    --font: 'IBM Plex Sans', system-ui, sans-serif;
    --mono: 'IBM Plex Mono', monospace;
}

*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font);
    background: var(--bg);
    color: var(--text);
    font-size: 13.5px;
    line-height: 1.6;
}

/* ── TOP BAR ── */
.topbar {
    position: sticky;
    top: 0;
    z-index: 100;
    background: #111;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 0 24px;
    height: 52px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .18);
}

.topbar-brand {
    font-weight: 600;
    font-size: 14px;
    letter-spacing: .02em;
    margin-right: 16px;
    white-space: nowrap;
}

.topbar-brand span {
    font-weight: 300;
    opacity: .75;
}

.topbar-nav {
    display: flex;
    gap: 2px;
    flex: 1;
    overflow-x: auto;
    scrollbar-width: none;
}

.topbar-nav::-webkit-scrollbar {
    display: none;
}

.nav-pill {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 5px 12px;
    border-radius: 20px;
    color: rgba(255, 255, 255, .8);
    text-decoration: none;
    font-size: 12.5px;
    font-weight: 500;
    white-space: nowrap;
    transition: background .15s, color .15s;
}

.nav-pill:hover,
.nav-pill.active {
    background: rgba(255, 255, 255, .18);
    color: #fff;
}

.nav-pill .dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: currentColor;
    opacity: .7;
}

.btn-pdf {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 16px;
    border-radius: 4px;
    background: #fff;
    color: var(--accent);
    font-family: var(--font);
    font-size: 12.5px;
    font-weight: 600;
    border: none;
    cursor: pointer;
    transition: background .15s;
    white-space: nowrap;
    margin-left: 8px;
}

.btn-pdf:hover {
    background: #e8f0fb;
}

.btn-pdf svg {
    flex-shrink: 0;
}

.btn-reset {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 16px;
    border-radius: 4px;
    background: transparent;
    color: #fff;
    font-family: var(--font);
    font-size: 12.5px;
    font-weight: 600;
    border: 1px solid rgba(255, 255, 255, 0.4);
    cursor: pointer;
    transition: background .15s, border-color .15s;
    white-space: nowrap;
    margin-left: 8px;
}

.btn-reset:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: #fff;
}

.btn-reset svg {
    flex-shrink: 0;
}

/* ── LAYOUT ── */
.page-layout {
    display: grid;
    grid-template-columns: 220px 1fr 220px;
    gap: 0;
    min-height: calc(100vh - 52px);
}

.wrapper {
    max-width: 860px;
    width: 100%;
    margin: 0 auto;
    padding: 28px 20px 60px;
    min-width: 0;
}

/* ── LEFT SIDEBAR ── */
.sidebar-left {
    position: sticky;
    top: 52px;
    height: calc(100vh - 52px);
    overflow-y: auto;
    padding: 16px 0 24px 16px;
    border-right: 1px solid var(--border-light);
    background: #fff;
    scrollbar-width: thin;
    scrollbar-color: #ddd transparent;
}

.sidebar-left::-webkit-scrollbar {
    width: 4px;
}

.sidebar-left::-webkit-scrollbar-thumb {
    background: #ddd;
    border-radius: 2px;
}

.sidebar-left .side-nav-title {
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .08em;
    color: #999;
    padding: 0 12px;
    margin-bottom: 8px;
}

.side-nav-group {
    margin-bottom: 14px;
}

.side-nav-group-label {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    font-size: 12px;
    font-weight: 600;
    color: #222;
    text-decoration: none;
    border-radius: 4px 0 0 4px;
    transition: background .12s;
}

.side-nav-group-label:hover {
    background: #f0f0f0;
}

.side-nav-group-label .side-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #bbb;
    flex-shrink: 0;
}

.side-nav-group-label.active {
    background: #f0f0f0;
}

.side-nav-group-label.active .side-dot {
    background: #222;
}

.side-nav-items {
    list-style: none;
    padding: 2px 0 0 24px;
}

.side-nav-items li a {
    display: block;
    padding: 3px 10px;
    font-size: 11.5px;
    color: #777;
    text-decoration: none;
    border-radius: 3px;
    transition: color .12s, background .12s;
    line-height: 1.4;
}

.side-nav-items li a:hover {
    color: #222;
    background: #f5f5f5;
}

/* ── RIGHT SIDEBAR ── */
.sidebar-right {
    position: sticky;
    top: 52px;
    height: calc(100vh - 52px);
    overflow-y: auto;
    padding: 16px 16px 24px 0;
    border-left: 1px solid var(--border-light);
    background: #fff;
    scrollbar-width: thin;
    scrollbar-color: #ddd transparent;
}

.sidebar-right::-webkit-scrollbar {
    width: 4px;
}

.sidebar-right::-webkit-scrollbar-thumb {
    background: #ddd;
    border-radius: 2px;
}

.sidebar-right .side-panel-title {
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .08em;
    color: #999;
    padding: 0 12px;
    margin-bottom: 10px;
}

.ref-group {
    margin-bottom: 14px;
    padding: 0 12px;
}

.ref-group-label {
    font-size: 11px;
    font-weight: 600;
    color: #333;
    text-transform: uppercase;
    letter-spacing: .04em;
    margin-bottom: 6px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.ref-group-label svg {
    flex-shrink: 0;
    color: #888;
}

.ref-link {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 5px 8px;
    font-size: 11.5px;
    color: #555;
    text-decoration: none;
    border-radius: 4px;
    transition: background .12s, color .12s;
    line-height: 1.35;
}

.ref-link:hover {
    background: #f0f0f0;
    color: #111;
}

.ref-link svg {
    flex-shrink: 0;
    color: #aaa;
}

.ref-divider {
    border: none;
    border-top: 1px solid #eee;
    margin: 10px 12px;
}

/* ── PAGE HEADER ── */
.page-header {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 20px 24px;
    margin-bottom: 20px;
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 12px;
    box-shadow: var(--shadow);
}

.page-header .hfield {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.page-header label {
    font-size: 11px;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: .06em;
}

.page-header input[type=text],
.page-header input[type=date] {
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 5px 8px;
    font-family: var(--font);
    font-size: 13px;
    color: var(--text);
    background: var(--bg);
}

.page-header input:focus {
    outline: 2px solid var(--accent-mid);
    outline-offset: 1px;
}

.hfield-wide {
    grid-column: 1 / -1;
}

/* ── SECTION ── */
.section {
    margin-bottom: 20px;
    border-radius: var(--radius);
    border: 1px solid var(--border);
    background: var(--surface);
    overflow: hidden;
    box-shadow: var(--shadow);
}

.section-head {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 13px 18px;
    cursor: pointer;
    user-select: none;
    border-bottom: 1px solid var(--border-light);
}

.section-head:hover {
    background: var(--bg);
}

.section-num {
    font-family: var(--mono);
    font-size: 10px;
    font-weight: 500;
    color: #fff;
    background: var(--accent);
    padding: 2px 6px;
    border-radius: 3px;
    letter-spacing: .04em;
}

.section-title {
    font-weight: 600;
    font-size: 14px;
    flex: 1;
}

.chevron {
    width: 18px;
    height: 18px;
    color: var(--text-secondary);
    transition: transform .2s;
}

.section.collapsed .chevron {
    transform: rotate(-90deg);
}

.section-body {
    padding: 16px 18px 20px;
}

.section.collapsed .section-body {
    display: none;
}

/* ── SUBSECTION ── */
.sub {
    margin-bottom: 18px;
    padding-bottom: 18px;
    border-bottom: 1px solid var(--border-light);
}

.sub:last-child {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.sub-title {
    font-size: 11.5px;
    font-weight: 600;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: .07em;
    margin-bottom: 10px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.sub-title::after {
    content: '';
    flex: 1;
    height: 1px;
    background: var(--border-light);
}

/* ── FIELDS ── */
.fields {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px 16px;
}

.fields.cols-3 {
    grid-template-columns: 1fr 1fr 1fr;
}

.fields.cols-1 {
    grid-template-columns: 1fr;
}

.field {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.field.span-2 {
    grid-column: span 2;
}

.field.span-3 {
    grid-column: 1 / -1;
}

.field label {
    font-size: 11.5px;
    font-weight: 500;
    color: var(--text-secondary);
}

.field input[type=text],
.field input[type=number],
.field input[type=date],
.field select,
.field textarea {
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 6px 8px;
    font-family: var(--font);
    font-size: 13px;
    color: var(--text);
    background: var(--bg);
    width: 100%;
    transition: border-color .15s;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
    outline: 2px solid var(--accent-mid);
    outline-offset: 1px;
    border-color: var(--accent-mid);
    background: #fff;
}

.field textarea {
    resize: vertical;
    min-height: 56px;
}

.field .unit {
    font-size: 11px;
    color: var(--text-secondary);
    margin-top: 1px;
}

/* ── INLINE UNIT FIELD ── */
.input-unit {
    display: flex;
    align-items: center;
    gap: 0;
}

.input-unit input {
    border-radius: 4px 0 0 4px !important;
    flex: 1;
}

.input-unit .badge-unit {
    background: var(--border-light);
    border: 1px solid var(--border);
    border-left: none;
    border-radius: 0 4px 4px 0;
    padding: 6px 8px;
    font-size: 11px;
    color: var(--text-secondary);
    white-space: nowrap;
    font-family: var(--mono);
}

/* ── RADIOS / CHECKBOXES ── */
.option-row {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
    margin-top: 3px;
}

.option-row label {
    display: flex;
    align-items: center;
    gap: 4px;
    cursor: pointer;
    font-size: 13px;
}

.option-row input[type=radio],
.option-row input[type=checkbox] {
    accent-color: var(--accent);
    width: 13px;
    height: 13px;
    cursor: pointer;
}

.option-label {
    font-size: 11.5px;
    font-weight: 500;
    color: var(--text-secondary);
    margin-bottom: 4px;
}

/* ── TOGGLE CHIPS ── */
.chips {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
}

.chip {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 3px 8px;
    border-radius: 12px;
    border: 1px solid var(--border);
    background: var(--bg);
    cursor: pointer;
    font-size: 12px;
    transition: all .12s;
    user-select: none;
}

.chip input {
    display: none;
}

.chip:has(input:checked) {
    background: #222;
    border-color: #222;
    color: #fff;
    font-weight: 500;
}

/* ── RISK BOXES ── */
.risk-group {
    background: var(--bg);
    border: 1px solid var(--border-light);
    border-radius: 4px;
    padding: 10px 12px;
    margin-bottom: 10px;
}

.risk-group-title {
    font-size: 11.5px;
    font-weight: 600;
    color: var(--red);
    text-transform: uppercase;
    letter-spacing: .06em;
    margin-bottom: 8px;
}

.risk-items {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.risk-item {
    display: flex;
    align-items: flex-start;
    gap: 7px;
    cursor: pointer;
    font-size: 13px;
    line-height: 1.4;
}

.risk-item input {
    accent-color: var(--red);
    margin-top: 2px;
    width: 13px;
    height: 13px;
    cursor: pointer;
    flex-shrink: 0;
}

/* ── VITALS GRID ── */
.vitals-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
}

.vital-card {
    background: var(--bg);
    border: 1px solid var(--border-light);
    border-radius: 4px;
    padding: 8px 10px;
}

.vital-card label {
    font-size: 10.5px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .05em;
    color: var(--text-secondary);
    display: block;
    margin-bottom: 4px;
}

.vital-card .input-unit input {
    background: #fff;
}

/* ── SECTION COLORS ── */
#anamnese .section-num {
    background: #222;
}

#exame .section-num {
    background: #333;
}

#avaliacao .section-num {
    background: #444;
}

#conduta .section-num {
    background: #555;
}

/* ── AVALIAÇÃO / CONDUTA ── */
.dx-block {
    background: #f5f5f5;
    border: 1px solid #ccc;
    border-radius: 4px;
    padding: 12px 14px;
    margin-bottom: 10px;
}

.dx-block label {
    font-size: 12px;
    font-weight: 600;
    color: #222;
    display: block;
    margin-bottom: 6px;
}

.dx-block textarea {
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 6px 8px;
    font-family: var(--font);
    font-size: 13px;
    width: 100%;
    resize: vertical;
    min-height: 52px;
    background: #fff;
}

.dx-block textarea:focus {
    outline: 2px solid #444;
    outline-offset: 1px;
}

.conduta-block {
    background: #f5f5f5;
    border: 1px solid #ccc;
    border-radius: 4px;
    padding: 12px 14px;
    margin-bottom: 10px;
}

.conduta-block label {
    font-size: 12px;
    font-weight: 600;
    color: #333;
    display: block;
    margin-bottom: 6px;
}

.conduta-block textarea {
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 6px 8px;
    font-family: var(--font);
    font-size: 13px;
    width: 100%;
    resize: vertical;
    min-height: 64px;
    background: #fff;
}

.conduta-block textarea:focus {
    outline: 2px solid #444;
    outline-offset: 1px;
}

/* ── PRINT / PDF ── */
/* ── PRINT ── */
#print-view {
    display: none;
}

@media print {
    body {
        background: #fff;
        color: #000;
    }

    .topbar,
    .page-layout,
    .modal-overlay {
        display: none !important;
    }

    #print-view {
        display: block !important;
        padding: 20px;
        max-width: 800px;
        margin: 0 auto;
    }
}

/* ── SECTION ANCHOR OFFSET ── */
.anchor {
    scroll-margin-top: 64px;
}

.section {
    scroll-margin-top: 64px;
}

/* ── RESPONSIVE ── */
@media (max-width: 1200px) {
    .page-layout {
        grid-template-columns: 200px 1fr;
    }

    .sidebar-right {
        display: none;
    }
}

@media (max-width: 860px) {
    .page-layout {
        display: block;
    }

    .sidebar-left {
        display: none;
    }
}

@media (max-width: 600px) {
    .fields {
        grid-template-columns: 1fr;
    }

    .fields.cols-3 {
        grid-template-columns: 1fr 1fr;
    }

    .vitals-grid {
        grid-template-columns: 1fr 1fr;
    }

    .page-header {
        grid-template-columns: 1fr 1fr;
    }

    .topbar-brand {
        display: none;
    }

    .field.span-2,
    .field.span-3 {
        grid-column: 1/-1;
    }
}

/* ── SCREEN TIME BOX ── */
.screen-time-box {
    background: #f9f9f9;
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 12px 14px;
    margin-top: 10px;
}

.screen-time-box .sub-title {
    margin-bottom: 10px;
}

/* ── MODAL (MARCOS DESENVOLVIMENTO) ── */
.modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 1000;
    background: rgba(0, 0, 0, .45);
    justify-content: center;
    align-items: flex-start;
    padding: 40px 20px;
    overflow-y: auto;
}

.modal-overlay.active {
    display: flex;
}

.modal-box {
    background: #fff;
    border-radius: 8px;
    width: 100%;
    max-width: 780px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, .22);
    animation: modalIn .2s ease;
}

@keyframes modalIn {
    from {
        opacity: 0;
        transform: translateY(-20px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 20px;
    border-bottom: 1px solid var(--border-light);
}

.modal-header h2 {
    font-size: 15px;
    font-weight: 600;
    color: #111;
}

.modal-header .modal-age-badge {
    font-size: 12px;
    background: #222;
    color: #fff;
    padding: 3px 10px;
    border-radius: 12px;
    font-weight: 500;
}

.modal-close {
    background: none;
    border: 1px solid var(--border);
    border-radius: 4px;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 16px;
    color: #555;
    transition: background .15s;
}

.modal-close:hover {
    background: #f0f0f0;
}

.modal-body {
    padding: 16px 20px 20px;
    max-height: 65vh;
    overflow-y: auto;
}

.modal-body::-webkit-scrollbar {
    width: 6px;
}

.modal-body::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 3px;
}

.modal-no-milestones {
    text-align: center;
    padding: 32px 20px;
    color: #888;
    font-size: 13px;
}

.milestone-group {
    margin-bottom: 18px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--border-light);
}

.milestone-group:last-child {
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}

.milestone-group-title {
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .05em;
    color: #222;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.milestone-group-title .age-range {
    font-family: var(--mono);
    font-size: 10px;
    background: #eee;
    padding: 2px 6px;
    border-radius: 3px;
    color: #555;
}

.milestone-item {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    padding: 6px 0;
}

.milestone-item input[type=checkbox] {
    accent-color: #222;
    width: 14px;
    height: 14px;
    margin-top: 2px;
    cursor: pointer;
    flex-shrink: 0;
}

.milestone-item-content {
    flex: 1;
}

.milestone-item-name {
    font-size: 13px;
    font-weight: 500;
    color: #111;
}

.milestone-item-desc {
    font-size: 11.5px;
    color: #777;
    margin-top: 2px;
    line-height: 1.45;
}

.milestone-obs {
