scriptContent:
// ── Global state and auto-save variables ──
let savedMilestones = new Set();

// ── Toggle section ──
function toggleSection(id) {
    const el = document.getElementById(id);
    el.classList.toggle('collapsed');
}

// ── Highlight active nav on scroll ──
const anchors = ['anamnese', 'exame', 'avaliacao', 'conduta'];
const pills = document.querySelectorAll('.nav-pill');
const observer = new IntersectionObserver(entries => {
    entries.forEach(e => {
        if (e.isIntersecting) {
            const id = e.target.id;
            pills.forEach(p => {
                p.classList.toggle('active', p.getAttribute('href') === '#' + id);
            });
        }
    });
}, { rootMargin: '-52px 0px -80% 0px', threshold: 0 });
anchors.forEach(id => {
    const el = document.getElementById(id);
    if (el) observer.observe(el);
});

// ── Default consultation date to today ──
(function () {
    const today = new Date();
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, '0');
    const dd = String(today.getDate()).padStart(2, '0');
    document.getElementById('dataConsulta').value = `${yyyy}-${mm}-${dd}`;
})();

// ── Auto-calculate age ──
function calcularIdade() {
    const nascInput = document.getElementById('dataNascimento').value;
    const consultaInput = document.getElementById('dataConsulta').value;
    const idadeField = document.getElementById('idadeCalculada');
    if (!nascInput) { idadeField.value = ''; return; }
    const nasc = new Date(nascInput + 'T00:00:00');
    const ref = consultaInput ? new Date(consultaInput + 'T00:00:00') : new Date();
    if (nasc > ref) { idadeField.value = 'Data inválida'; return; }
    let anos = ref.getFullYear() - nasc.getFullYear();
    let meses = ref.getMonth() - nasc.getMonth();
    let dias = ref.getDate() - nasc.getDate();
    if (dias < 0) { meses--; const prevMonth = new Date(ref.getFullYear(), ref.getMonth(), 0); dias += prevMonth.getDate(); }
    if (meses < 0) { anos--; meses += 12; }
    const parts = [];
    if (anos > 0) parts.push(anos + (anos === 1 ? ' ano' : ' anos'));
    if (meses > 0) parts.push(meses + (meses === 1 ? ' mês' : ' meses'));
    if (dias > 0 || parts.length === 0) parts.push(dias + (dias === 1 ? ' dia' : ' dias'));
    idadeField.value = parts.join(', ');
}
document.getElementById('dataNascimento').addEventListener('change', calcularIdade);
document.getElementById('dataConsulta').addEventListener('change', calcularIdade);

// ── BMI calculation logic with manual override ──
let imcManual = false;
function calcularIMC() {
    if (imcManual) return;
    const pesoInput = document.getElementById('input-peso');
    const alturaInput = document.getElementById('input-altura');
    const imcInput = document.getElementById('input-imc');
    if (!pesoInput || !alturaInput || !imcInput) return;
    const peso = parseFloat(pesoInput.value);
    const altura = parseFloat(alturaInput.value);
    if (!isNaN(peso) && !isNaN(altura) && altura > 0) {
        const alturaMetros = altura / 100;
        const imc = peso / (alturaMetros * alturaMetros);
        imcInput.value = imc.toFixed(2);
    } else {
        imcInput.value = '';
    }
}
document.getElementById('input-peso').addEventListener('input', calcularIMC);
document.getElementById('input-altura').addEventListener('input', calcularIMC);
document.getElementById('input-imc').addEventListener('input', function (e) {
    if (e.target.value === '') {
        imcManual = false;
        calcularIMC();
    } else {
        imcManual = true;
    }
});

// ── Diagnósticos Quick Fill Helper ──
function fillDx(id, text) {
    const el = document.getElementById(id);
    if (el) {
        el.value = text;
        el.dispatchEvent(new Event('input', { bubbles: true }));
    }
}

