const FAIXAS = [
    { label: 'Nascimento a 6 meses', min: 0, max: 6 },
    { label: '6 meses a 1 ano e meio', min: 6, max: 18 },
    { label: '1 ano e meio a 3 anos e meio', min: 18, max: 42 },
    { label: '3 anos e meio a 5 anos', min: 42, max: 60 },
    { label: '5 a 6 anos', min: 60, max: 72 }
];

function getIdadeEmMeses() {
    const nascInput = document.getElementById('dataNascimento').value;
    const consultaInput = document.getElementById('dataConsulta').value;
    if (!nascInput) return null;
    const nasc = new Date(nascInput + 'T00:00:00');
    const ref = consultaInput ? new Date(consultaInput + 'T00:00:00') : new Date();
    if (nasc > ref) return null;
    return (ref.getFullYear() - nasc.getFullYear()) * 12 + (ref.getMonth() - nasc.getMonth()) + (ref.getDate() >= nasc.getDate() ? 0 : -1);
}

function openMarcosModal() {
    const modal = document.getElementById('marcosModal');
    const body = document.getElementById('marcosBody');
    const badge = document.getElementById('modalAgeBadge');
    const meses = getIdadeEmMeses();

    if (meses === null) {
        badge.textContent = '—';
        body.innerHTML = '<div class="modal-no-milestones">Preencha a data de nascimento para visualizar os marcos esperados.</div>';
        modal.classList.add('active');
        return;
    }

    // Format age for badge
    const anos = Math.floor(meses / 12);
    const mResto = meses % 12;
    let ageStr = '';
    if (anos > 0) ageStr += anos + (anos === 1 ? ' ano' : ' anos');
    if (mResto > 0) ageStr += (ageStr ? ' e ' : '') + mResto + (mResto === 1 ? ' mês' : ' meses');
    if (!ageStr) ageStr = 'Recém-nascido';
    badge.textContent = ageStr;

    // Filter relevant milestones: show current age group + previous group
    let relevantFaixas = FAIXAS.filter(f => meses >= f.min - 3 && meses < f.max + 6);
    if (relevantFaixas.length === 0) {
        // Show closest group
        if (meses < 0) relevantFaixas = [FAIXAS[0]];
        else relevantFaixas = [FAIXAS[FAIXAS.length - 1]];
    }

    let html = '';
    relevantFaixas.forEach(faixa => {
        const marcosGrupo = MARCOS.filter(m => m.minMeses >= faixa.min && m.minMeses < faixa.max);
        if (marcosGrupo.length === 0) return;
        html += `<div class="milestone-group">`;
        html += `<div class="milestone-group-title">${faixa.label} <span class="age-range">${faixa.min}–${faixa.max} meses</span></div>`;
        marcosGrupo.forEach((m, i) => {
            const isExpected = meses >= m.minMeses;
            const isChecked = savedMilestones.has(`marco_${faixa.min}_${i}`);
            html += `<div class="milestone-item" style="${isExpected ? '' : 'opacity:.55'}">`;
            html += `<input type="checkbox" id="marco_${faixa.min}_${i}" ${isChecked ? 'checked' : ''}>`;
            html += `<label for="marco_${faixa.min}_${i}" class="milestone-item-content">`;
            html += `<div class="milestone-item-name">${m.nome}${isExpected ? '' : ' <span style="font-size:10px;color:#999">(ainda não esperado)</span>'}</div>`;
            html += `<div class="milestone-item-desc">${m.desc}</div>`;
            html += `</label></div>`;
        });
        html += `</div>`;
    });

    if (!html) {
        html = '<div class="modal-no-milestones">Idade fora da faixa de marcos disponíveis (0–72 meses).</div>';
    }

    body.innerHTML = html;
    modal.classList.add('active');
}

function closeMarcosModal() {
    document.getElementById('marcosModal').classList.remove('active');
}
// Close modal on overlay click
document.getElementById('marcosModal').addEventListener('click', function (e) {
    if (e.target === this) closeMarcosModal();
});
// Close on Escape
document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') closeMarcosModal();
});
function generatePDF() {
    let printView = document.getElementById('print-view');
    if (!printView) {
        printView = document.createElement('div');
        printView.id = 'print-view';
        document.body.appendChild(printView);
    }
    printView.innerHTML = '';

    let html = '';

    function getFieldValue(el) {
        let val = '';
        let inputs = el.querySelectorAll('input:not([type="checkbox"]):not([type="radio"]), textarea, select');
        if (inputs.length > 0) {
            let vals = Array.from(inputs).map(inp => {
                let v = inp.value.trim();
                if (v && inp.nextElementSibling && inp.nextElementSibling.classList.contains('badge-unit')) {
                    v += ' ' + inp.nextElementSibling.textContent.trim();
                }
                return v;
            }).filter(v => v !== '');
            if (vals.length > 0) {
                val = vals.join(' ');
            }
        }
        let radios = el.querySelectorAll('input[type="radio"]:checked');
        if (radios.length > 0) {
            let rVals = Array.from(radios).map(r => r.parentElement.textContent.trim());
            val += (val ? ' — ' : '') + rVals.join(', ');
        }
        let checks = el.querySelectorAll('input[type="checkbox"]:checked');
        if (checks.length > 0) {
            let cVals = Array.from(checks).map(c => c.parentElement.textContent.trim());
            val += (val ? ' — ' : '') + cVals.join(', ');
        }
        return val;
    }

    // 1. IDENTIFICAÇÃO
    let identFields = [];
    document.querySelectorAll('.page-header .hfield').forEach(field => {
        let label = field.querySelector('label')?.textContent.trim() || '';
        let val = getFieldValue(field);
        if (label.endsWith(':')) label = label.slice(0, -1).trim();
        if (val && label) {
            identFields.push({ label, val, isLong: val.length > 60 });
        }
    });

    if (identFields.length > 0) {
        let identFieldsHtml = '';
