// ── state saving to localStorage ──
function saveFormState() {
    const data = {
        textValues: [],
        checkboxValues: [],
        radioValues: [],
        imcManual: imcManual,
        checkedMilestones: Array.from(savedMilestones)
    };

    const textElements = document.querySelectorAll('input:not([type="checkbox"]):not([type="radio"]):not(#marcosModal *), select:not(#marcosModal *), textarea:not(#marcosModal *)');
    textElements.forEach((el, index) => {
        data.textValues.push({ index, val: el.value });
    });

    const checkboxElements = document.querySelectorAll('input[type="checkbox"]:not(#marcosModal *)');
    checkboxElements.forEach((el, index) => {
        data.checkboxValues.push({ index, checked: el.checked });
    });

    const radioElements = document.querySelectorAll('input[type="radio"]:not(#marcosModal *)');
    radioElements.forEach((el, index) => {
        data.radioValues.push({ index, checked: el.checked });
    });

    localStorage.setItem('emr_ped_state', JSON.stringify(data));
}

function loadFormState() {
    const raw = localStorage.getItem('emr_ped_state');
    if (!raw) return;
    try {
        const data = JSON.parse(raw);

        if (data.imcManual !== undefined) {
            imcManual = data.imcManual;
        }

        if (data.checkedMilestones) {
            savedMilestones = new Set(data.checkedMilestones);
        }

        if (data.textValues) {
            const textElements = document.querySelectorAll('input:not([type="checkbox"]):not([type="radio"]):not(#marcosModal *), select:not(#marcosModal *), textarea:not(#marcosModal *)');
            data.textValues.forEach(item => {
                if (textElements[item.index]) {
                    textElements[item.index].value = item.val;
                }
            });
        }

        if (data.checkboxValues) {
            const checkboxElements = document.querySelectorAll('input[type="checkbox"]:not(#marcosModal *)');
            data.checkboxValues.forEach(item => {
                if (checkboxElements[item.index]) {
                    checkboxElements[item.index].checked = item.checked;
                }
            });
        }

        if (data.radioValues) {
            const radioElements = document.querySelectorAll('input[type="radio"]:not(#marcosModal *)');
            data.radioValues.forEach(item => {
                if (radioElements[item.index]) {
                    radioElements[item.index].checked = item.checked;
                }
            });
        }

        calcularIdade();

    } catch (e) {
        console.error('Error loading form state:', e);
    }
}

function resetForm() {
    if (!confirm("Tem certeza de que deseja limpar todo o formulário? Todos os dados salvos serão apagados definitivamente.")) {
        return;
    }

    localStorage.removeItem('emr_ped_state');
    imcManual = false;
    savedMilestones.clear();

    const textElements = document.querySelectorAll('input:not([type="checkbox"]):not([type="radio"]):not(#marcosModal *), select:not(#marcosModal *), textarea:not(#marcosModal *)');
    textElements.forEach(el => {
        if (el.id === 'dataConsulta') {
            const today = new Date();
            const yyyy = today.getFullYear();
            const mm = String(today.getMonth() + 1).padStart(2, '0');
            const dd = String(today.getDate()).padStart(2, '0');
            el.value = `${yyyy}-${mm}-${dd}`;
        } else {
            el.value = '';
        }
    });

    const checkboxElements = document.querySelectorAll('input[type="checkbox"]:not(#marcosModal *)');
    checkboxElements.forEach(el => {
        el.checked = false;
    });

    const radioElements = document.querySelectorAll('input[type="radio"]:not(#marcosModal *)');
    radioElements.forEach(el => {
        el.checked = false;
    });

    calcularIdade();
}

// Debounce helper
function debounce(func, wait) {
    let timeout;
    return function (...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait);
    };
}

// Listeners for auto-save
const debouncedSave = debounce(saveFormState, 500);
document.body.addEventListener('input', function (e) {
    if (!e.target.closest('#marcosModal')) {
        debouncedSave();
    }
});
document.body.addEventListener('change', function (e) {
    if (!e.target.closest('#marcosModal')) {
        debouncedSave();
    }
});

// Milestones modal checkbox listener
document.getElementById('marcosModal').addEventListener('change', function (e) {
    if (e.target && e.target.type === 'checkbox' && e.target.id.startsWith('marco_')) {
        if (e.target.checked) {
            savedMilestones.add(e.target.id);
        } else {
            savedMilestones.delete(e.target.id);
        }
        saveFormState();
    }
});

// --- QUEIXAS SECUNDÁRIAS E HMA SUMMARY ---
let secondaryComplaintCount = 1; // Start from 2 for S2

function addSecondaryComplaint() {
    secondaryComplaintCount++;
    const sNum = secondaryComplaintCount;
    const container = document.getElementById('secondary-complaints-container');

    const div = document.createElement('div');
    div.className = 'sub';
    div.innerHTML = `
        <div class="sub-title" style="display: flex; justify-content: space-between; align-items: center;">
            <span>Queixa Secundária (S${sNum})</span>
            <button type="button" onclick="this.closest('.sub').remove(); updateHdaSummary();" style="background: none; border: none; color: #d9534f; cursor: pointer; font-size: 12px; font-weight: bold;">Remover</button>
        </div>
        <div class="fields cols-1">
            <div class="field">
                <label>História da queixa S${sNum}</label>
                <textarea class="secondary-complaint-textarea" rows="3" placeholder="Descreva cronologicamente..." oninput="updateHdaSummary()"></textarea>
            </div>
        </div>
    `;
    container.appendChild(div);
}

function toggleHdaSummary() {
    const content = document.getElementById('hda-summary-content');
    const chevron = document.getElementById('hda-summary-chevron');
    if (content.style.display === 'none') {
        content.style.display = 'block';
        chevron.style.transform = 'rotate(180deg)';
        updateHdaSummary();
    } else {
        content.style.display = 'none';
        chevron.style.transform = 'rotate(0deg)';
    }
}

function updateHdaSummary() {
    const content = document.getElementById('hda-summary-content');
    if (!content || content.style.display === 'none') return;

    let summary = '';
    const hdaPrincipal = document.getElementById('hda-principal');
    if (hdaPrincipal && hdaPrincipal.value.trim()) {
        summary += 'HMA / Queixa Principal:\n' + hdaPrincipal.value.trim() + '\n\n';
    }

    const secondaryTextareas = document.querySelectorAll('.secondary-complaint-textarea');
    secondaryTextareas.forEach((textarea, index) => {
        if (textarea.value.trim()) {
            summary += 'Queixa Secundária S' + (index + 2) + ':\n' + textarea.value.trim() + '\n\n';
        }
    });

    if (!summary) {
        content.innerHTML = '<em style="color: #999;">Preencha a HMA ou queixas secundárias...</em>';
    } else {
        content.textContent = summary.trim();
    }
}

